class Solution:
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next

    def solve(self, head: ListNode) -> None:
        if not head:
            return head

        even_head = ListNode(0)
        odd_head = ListNode(0)
        even_tail = even_head
        odd_tail = odd_head
        current = head

        while current:
            if current.val % 2 == 0:
                even_tail.next = current
                even_tail = even_tail.next
            else:
                odd_tail.next = current
                odd_tail = odd_tail.next
            current = current.next

        even_tail.next = odd_head.next
        odd_tail.next = None

        return even_head.next
